import { ArrowRightLeft, Bike, Building2, Calculator, ChevronRight, CircleDollarSign, FileBarChart, HandCoins, Home, Menu, Plus, Receipt, Settings, TrendingUp, UserRound, Users, WalletCards, X } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { getSupabase, isSupabaseConfigured } from "./lib/supabase";
import { cancelRecord, createCarrier, createRider, listPartners, listRiders, loadAdvances, loadCarrierSheet, loadClosures, loadCosts, loadFinancialBI, loadFinancialSummary, loadRiderSheet, loadSettings, loadWeeklyCalendar, moveCarrierReceipts, previewCarrierReceiptMove, removeRiderSafely, riderHasHistory, saveAdvance, saveCarrierReceipts, saveClosure, saveCost, saveRiderPayments, saveSettings, saveTransfer, saveWeeklyCalendar, setCarrierActive, setRiderActive, signIn, signOut, updateCarrier, updateRider, type Period, type WeeklyCalendarEntry } from "./lib/finance";

const brl=(n:number)=>n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const moneyText=(n:number|string|null|undefined)=>Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});
const parseMoney=(value:FormDataEntryValue|string|null|undefined)=>{const raw=String(value??"").replace(/[^\d,.-]/g,"");if(!raw)return 0;const comma=raw.lastIndexOf(","),dot=raw.lastIndexOf(".");const decimal=Math.max(comma,dot);if(decimal<0)return Number(raw)||0;const decimals=raw.length-decimal-1;if(decimals===3&&comma<0&&raw.indexOf(".")===dot)return Number(raw.replace(/\./g,""))||0;const integer=raw.slice(0,decimal).replace(/[.,]/g,""),fraction=raw.slice(decimal+1).replace(/[.,]/g,"");return Number(`${integer||"0"}.${fraction}`)||0};
const cleanMoneyInput=(value:string)=>value.replace(/[^\d,.-]/g,"");
const monthNames=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
const periodDescription=(period:Period)=>`${period.numero_periodo}ª ${period.tipo_periodo==="quinzenal"?"quinzena":"semana"} de ${monthNames[period.mes-1]}/${period.ano}`;
const defaultPeriod:Period={tipo_periodo:"quinzenal",numero_periodo:1,mes:8,ano:2026};
const readStoredPeriod=()=>{if(typeof window==="undefined")return defaultPeriod;try{const value=JSON.parse(localStorage.getItem("sub-flex-period")??"") as Period;const limit=value.tipo_periodo==="semanal"?5:2;if((value.tipo_periodo==="semanal"||value.tipo_periodo==="quinzenal")&&value.mes>=1&&value.mes<=12&&value.ano>=2000&&value.ano<=2100&&value.numero_periodo>=1&&value.numero_periodo<=limit)return value}catch{}return defaultPeriod};
const menu=[["Início",Home],["Recebimentos",Building2],["Motoboys",Bike],["Custos",Receipt],["Vales e Extravios",HandCoins],["Sócios",Users],["Acerto entre Sócios",ArrowRightLeft],["Relatórios",FileBarChart],["BI Financeiro",TrendingUp],["Configurações",Settings]] as const;
const summary=[
  ["Total recebido",0,"in"],["Pago aos motoboys",0,"out"],["Custos totais",0,"out"],
  ["Vales e extravios",0,"warn"],["Lucro bruto",0,"info"],["Lucro real",0,"profit"],
] as const;
const pending:readonly [string,string,number,string][]=[];
const entries:readonly [string,string,string,number,string,string][]=[];
const costs:readonly [string,string,number,string,string][]=[];
const advances:readonly [string,string,number,string,string][]=[];
const launchOptions: readonly [string, LucideIcon][] = [["Custo",Receipt],["Vale",HandCoins],["Extravio",WalletCards],["Nova transportadora",Building2],["Novo motoboy",Bike]];

function Status({children}:{children:React.ReactNode}){const t=String(children).toLowerCase();return <span className={`status ${t.includes("pago")||t.includes("recebido")||t.includes("descontado")?"ok":t.includes("parcial")?"info":"wait"}`}>{children}</span>}
function PageHead({title,button,onAdd}:{title:string;button?:string;onAdd:()=>void}){return <div className="page-head"><div><span>SUB FLEX FINANCEIRO</span><h1>{title}</h1></div>{button&&<button className="btn primary" onClick={onAdd}><Plus/> {button}</button>}</div>}
function DataTable({heads,rows}:{heads:string[];rows:React.ReactNode[][]}){return <div className="table-wrap"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{c}</td>)}</tr>)}</tbody></table></div>}
function EmptyTable({heads}:{heads:string[]}){return <div className="table-wrap"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead></table><div className="empty-row">Nenhum registro neste período.</div></div>}
function MiniTotals({items}:{items:[string,string,string][]}){return <div className="mini-totals">{items.map(([l,v,c])=><div key={l}><span>{l}</span><b className={c}>{v}</b></div>)}</div>}

export default function App(){
 const [active,setActive]=useState("Início"),[drawer,setDrawer]=useState(false),[launch,setLaunch]=useState(false),[kind,setKind]=useState(""),[tab,setTab]=useState("Semanais"),[analysis,setAnalysis]=useState(false),[toast,setToast]=useState("");
 const [selectedPeriod,setSelectedPeriod]=useState<Period>(readStoredPeriod),[loadedPeriod,setLoadedPeriod]=useState<Period>(readStoredPeriod);
 const [carrierRevision,setCarrierRevision]=useState(0),[riderRevision,setRiderRevision]=useState(0),[savingQuick,setSavingQuick]=useState(false);
 const [authLoading,setAuthLoading]=useState(true),[authenticated,setAuthenticated]=useState(false),[userEmail,setUserEmail]=useState("");
 useEffect(()=>{const client=getSupabase();if(!client){setAuthLoading(false);return}client.auth.getSession().then(({data})=>{setAuthenticated(Boolean(data.session));setUserEmail(data.session?.user.email??"");setAuthLoading(false)});const {data}=client.auth.onAuthStateChange((_event,session)=>{setAuthenticated(Boolean(session));setUserEmail(session?.user.email??"")});return()=>data.subscription.unsubscribe()},[]);
 const close=()=>{setLaunch(false);setKind("")};
 const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(savingQuick)return;const form=new FormData(e.currentTarget);try{setSavingQuick(true);if(kind==="Nova transportadora"){await createCarrier(String(form.get("nome")??""),form.get("frequencia")==="semanal"?"semanal":"quinzenal");setCarrierRevision(x=>x+1);close();setToast("Transportadora salva com sucesso")}else if(kind==="Novo motoboy"){await createRider(String(form.get("nome")??""),form.get("frequencia")==="semanal"?"semanal":"quinzenal");setRiderRevision(x=>x+1);close();setToast("Motoboy salvo com sucesso")}else{close();setToast("Lançamento registrado")}}catch(error){setToast(error instanceof Error?error.message:"Não foi possível salvar o cadastro")}finally{setSavingQuick(false);setTimeout(()=>setToast(""),3000)}};
 const title=active;
 const quick=(k:string)=>{if(k==="Custo"){setTab("Fixos");setActive("Custos");return}if(k==="Vale"||k==="Extravio"){setTab(k==="Vale"?"Vales":"Extravios");setActive("Vales e Extravios");return}setKind(k);setLaunch(true)};
 const loadSelectedPeriod=()=>{const next={...selectedPeriod};setLoadedPeriod(next);localStorage.setItem("sub-flex-period",JSON.stringify(next))};
 const page=useMemo(()=>{
  const periodProps={selectedPeriod,loadedPeriod,onPeriodChange:setSelectedPeriod,onLoadPeriod:loadSelectedPeriod};
  if(active==="Início")return <DashboardPage onGo={setActive} onLaunch={quick} {...periodProps}/>;
  if(active==="Recebimentos")return <CarrierSheet key={carrierRevision} onNew={()=>quick("Nova transportadora")} {...periodProps}/>;
  if(active==="Motoboys")return <RiderSheet key={riderRevision} onNew={()=>quick("Novo motoboy")} {...periodProps}/>;
  if(active==="Custos")return <CostsPage tab={tab} setTab={setTab} {...periodProps}/>;
  if(active==="Vales e Extravios")return <AdvancesPage tab={tab} setTab={setTab} {...periodProps}/>;
  if(active==="Sócios")return <PartnersPage tab={tab} setTab={setTab} {...periodProps}/>;
  if(active==="Acerto entre Sócios")return <SettlementPersistentPage {...periodProps}/>;
  if(active==="BI Financeiro")return <FinancialBI/>;
  if(active==="Configurações")return <SettingsPage/>;
  return <ReportsPage {...periodProps}/>;
 },[active,tab,analysis,carrierRevision,riderRevision,selectedPeriod,loadedPeriod]);
 if(!isSupabaseConfigured())return <SetupRequired/>;
 if(authLoading)return <div className="auth-shell"><div className="auth-loading">Carregando dados com segurança...</div></div>;
 if(!authenticated)return <LoginScreen onSuccess={()=>setAuthenticated(true)}/>;
 return <div className="app"><aside className={drawer?"open":""}><div className="brand"><div><TrendingUp/></div><span><b>Sub Flex</b>Financeiro</span><button onClick={()=>setDrawer(false)}><X/></button></div><nav>{menu.map(([l,I])=><button key={l} className={active===l?"active":""} onClick={()=>{setActive(l);setDrawer(false);setTab(l==="Motoboys"?"Semanais":l==="Custos"?"Fixos":l==="Vales e Extravios"?"Vales":l==="Sócios"?"Caio":tab)}}><I/>{l}</button>)}</nav><button className="user" onClick={()=>signOut()}><UserRound/><span><b>{userEmail}</b>Sair do sistema</span></button></aside><main><div className="mobile-top"><button onClick={()=>setDrawer(true)}><Menu/></button><b>Sub Flex</b><span>SF</span></div><div className="content">{page}</div></main><nav className="mobile-nav"><button className={active==="Início"?"active":""} onClick={()=>setActive("Início")}><Home/>Início</button><button onClick={()=>setLaunch(true)}><span className="launch"><Plus/></span>Lançar</button><button className={active==="Motoboys"?"active":""} onClick={()=>setActive("Motoboys")}><Bike/>Motoboys</button><button className={active==="Sócios"?"active":""} onClick={()=>setActive("Sócios")}><Users/>Sócios</button><button onClick={()=>setDrawer(true)}><Menu/>Mais</button></nav><button className="fab" onClick={()=>setLaunch(true)}><Plus/></button>
 {launch&&<div className="overlay" onMouseDown={close}><div className="modal" onMouseDown={e=>e.stopPropagation()}>{!kind?<><ModalHead title="Novo lançamento" close={close}/><p className="modal-sub">Escolha um lançamento avulso</p><div className="launch-grid">{launchOptions.map(([l,I])=><button key={l} onClick={()=>setKind(l)}><I/><span><b>{l}</b>cadastro rápido</span><ChevronRight/></button>)}</div></>:<form onSubmit={save}><ModalHead title={kind} close={close}/><ShortForm kind={kind}/><div className="form-actions"><button type="button" onClick={()=>setKind("")} className="btn ghost">Voltar</button><button className="btn primary" disabled={savingQuick}>{savingQuick?"Salvando...":"Salvar"}</button></div></form>}</div></div>}{toast&&<div className="toast">✓ {toast}</div>}</div>
}

type CarrierRow={id:string;name:string;type:"Semanal"|"Quinzenal";registrationType:"Semanal"|"Quinzenal";active:boolean;hasReceipt:boolean;value:string;owner:"Caio"|"José";status:"Recebido"|"Pendente"};
type PeriodProps={selectedPeriod:Period;loadedPeriod:Period;onPeriodChange:(period:Period)=>void;onLoadPeriod:()=>void};
function calculateSettlement(summary:any,closure:any){const caio=summary.partners.find((p:any)=>p.nome==="Caio")??{id:null,nome:"Caio",received:0,paid:0,percentual_participacao:50},jose=summary.partners.find((p:any)=>p.nome==="José")??{id:null,nome:"José",received:0,paid:0,percentual_participacao:50},partCaio=summary.profit*Number(caio.percentual_participacao)/100,partJose=summary.profit*Number(jose.percentual_participacao)/100,saldoCaio=caio.received-caio.paid,saldoJose=jose.received-jose.paid,diffCaio=saldoCaio-partCaio,diffJose=saldoJose-partJose,payer=diffCaio>0?caio:jose,receiver=diffCaio>0?jose:caio,predicted=Math.abs(diffCaio),paid=(closure?.repasses_socios??[]).filter((r:any)=>r.status!=="cancelado").reduce((a:number,r:any)=>a+Number(r.valor_pago),0),remaining=Math.max(0,predicted-paid);return{caio,jose,partCaio,partJose,saldoCaio,saldoJose,diffCaio,diffJose,payer,receiver,predicted,paid,remaining}}
function PeriodFilter({selectedPeriod,loadedPeriod,onPeriodChange,onLoadPeriod}:PeriodProps){const change=(changes:Partial<Period>)=>onPeriodChange({...selectedPeriod,...changes});return <><div className="sheet-toolbar period-filter"><label>Mês<select value={selectedPeriod.mes} onChange={e=>change({mes:Number(e.target.value)})}>{monthNames.map((month,index)=><option key={month} value={index+1}>{month}</option>)}</select></label><label>Ano<input type="number" min="2000" max="2100" value={selectedPeriod.ano} onChange={e=>change({ano:Number(e.target.value)})}/></label><label>Frequência<select value={selectedPeriod.tipo_periodo} onChange={e=>change({tipo_periodo:e.target.value as Period["tipo_periodo"],numero_periodo:1})}><option value="semanal">Semanais</option><option value="quinzenal">Quinzenais</option></select></label><label>Período<select value={selectedPeriod.numero_periodo} onChange={e=>change({numero_periodo:Number(e.target.value)})}>{Array.from({length:selectedPeriod.tipo_periodo==="semanal"?5:2},(_,index)=><option key={index+1} value={index+1}>{index+1}ª {selectedPeriod.tipo_periodo==="semanal"?"semana":"quinzena"}</option>)}</select></label><button className="btn ghost" type="button" onClick={onLoadPeriod}>Carregar período</button></div><div className="loaded-period">Período carregado: <b>{monthNames[loadedPeriod.mes-1]}/{loadedPeriod.ano} • {loadedPeriod.numero_periodo}ª {loadedPeriod.tipo_periodo==="semanal"?"semana":"quinzena"}</b></div></>}
function DashboardPage({onGo,onLaunch,...periodProps}:{onGo:(s:string)=>void;onLaunch:(s:string)=>void}&PeriodProps){const {loadedPeriod}=periodProps,[data,setData]=useState<any>(null),[error,setError]=useState("");useEffect(()=>{setData(null);setError("");Promise.all([loadFinancialSummary(loadedPeriod),loadClosures(loadedPeriod)]).then(([summary,closure])=>setData({summary,closure})).catch(e=>setError(e.message))},[loadedPeriod]);if(error)return <><PeriodFilter {...periodProps}/><div className="data-state error">Erro ao carregar dashboard: {error}</div></>;if(!data)return <><PeriodFilter {...periodProps}/><div className="data-state">Carregando dados financeiros...</div></>;const summary=data.summary,{caio,jose,payer,receiver,remaining}=calculateSettlement(summary,data.closure),cards=[["Total recebido",summary.received,"in"],["Pago aos motoboys",summary.paidRiders,"out"],["Custos totais",summary.paidCosts,"out"],["Lucro real",summary.profit,"profit"]];return <><div className="period-bar"><PeriodFilter {...periodProps}/><button className="btn primary" onClick={()=>onLaunch("Custo")}><Plus/> Novo lançamento</button></div><div className="quick"><span>Atalhos</span><button onClick={()=>onGo("Recebimentos")}>Transportadoras</button><button onClick={()=>onGo("Motoboys")}>Motoboys</button><button onClick={()=>onGo("Custos")}>Custos</button><button onClick={()=>onGo("Vales e Extravios")}>Vales</button></div><div className="summary-grid dashboard-real">{cards.map(([l,v,t]:any)=><div className={`summary ${t}`} key={l}><span>{l}</span><b>{brl(v)}</b></div>)}</div>{loadedPeriod.tipo_periodo==="quinzenal"&&<div className="payment-consolidation"><div><span>RESUMO DE PAGAMENTOS DA QUINZENA</span><small>Semanais incluídos: {summary.includedWeeks.length?`semanas ${summary.includedWeeks.join(" e ")}`:"nenhuma semana configurada"}</small></div><dl><div><dt>Quinzenais</dt><dd>{brl(summary.paidRidersFortnightly)}</dd></div><div><dt>Semanais incluídos</dt><dd>{brl(summary.paidRidersWeekly)}</dd></div><div className="payment-total"><dt>TOTAL GERAL</dt><dd>{brl(summary.paidRiders)}</dd></div></dl></div>}<section><div className="section-title"><h2>Resumo dos sócios</h2><span>Dados reais de {periodDescription(loadedPeriod)}</span></div><div className="partners"><Partner name="Caio" received={caio.received} paid={caio.paid} balance={caio.received-caio.paid} note="Saldo calculado"/><Partner name="José" received={jose.received} paid={jose.paid} balance={jose.received-jose.paid} note="Saldo calculado"/></div><div className={`settlement-alert ${remaining>.01?"due":"balanced"}`}><div className="settlement-alert-icon"><ArrowRightLeft/></div><div className="settlement-alert-copy"><span>ACERTO ENTRE SÓCIOS</span>{remaining>.01?<h2><strong>{payer.nome}</strong> deve repassar <b>{brl(remaining)}</b> para <strong>{receiver.nome}</strong></h2>:<h2>Sócios acertados neste período. Nenhum repasse necessário.</h2>}<p>{periodDescription(loadedPeriod)}</p></div><button className="btn ghost" onClick={()=>onGo("Acerto entre Sócios")}>Ver acerto completo</button></div></section></>}
function CostsPage({tab,setTab,...periodProps}:{tab:string;setTab:(s:string)=>void}&PeriodProps){
 const {loadedPeriod}=periodProps,[rows,setRows]=useState<any[]>([]),[partners,setPartners]=useState<any[]>([]),[loading,setLoading]=useState(true),[open,setOpen]=useState(false),[edit,setEdit]=useState<any>(null),[error,setError]=useState("");
 const reload=async()=>{try{setLoading(true);const [r,p]=await Promise.all([loadCosts(loadedPeriod),listPartners()]);setRows(r);setPartners(p);setError("")}catch(e){setError(e instanceof Error?e.message:"Erro")}finally{setLoading(false)}};
 useEffect(()=>{reload()},[loadedPeriod]);
 const visible=rows.filter(r=>r.tipo===(tab==="Variáveis"?"variavel":"fixo"));
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget),date=String(f.get("data"));await saveCost({id:edit?.id,tipo:tab==="Variáveis"?"variavel":"fixo",categoria:f.get("categoria"),descricao:f.get("descricao"),valor:parseMoney(f.get("valor")),data:date,mes:Number(date.slice(5,7)),ano:Number(date.slice(0,4)),status:f.get("status"),pago_por_socio_id:f.get("socio")||null,observacoes:f.get("observacoes")});setOpen(false);setEdit(null);await reload()};
 return <Module><PageHead title="Custos" button="Adicionar custo" onAdd={()=>setOpen(true)}/><PeriodFilter {...periodProps}/><Tabs values={["Fixos","Variáveis"]} value={tab==="Variáveis"?tab:"Fixos"} set={setTab}/>{loading?<div className="data-state">Carregando custos...</div>:error?<div className="data-state error">{error}</div>:<><MiniTotals items={[["Total da aba",brl(visible.reduce((a,r)=>a+Number(r.valor),0)),"out"],["Total pago",brl(visible.filter(r=>r.status==="pago").reduce((a,r)=>a+Number(r.valor),0)),"in"],["Pendente",brl(visible.filter(r=>r.status==="pendente").reduce((a,r)=>a+Number(r.valor),0)),"warn"]]}/>{visible.length?<DataTable heads={["Descrição","Data","Valor","Pago por","Status","Ações"]} rows={visible.map(r=>[r.descricao,r.data,brl(Number(r.valor)),r.socios?.nome??"Não informado",<Status>{r.status}</Status>,<span className="row-actions"><button onClick={()=>{setEdit(r);setOpen(true)}}>Editar</button><button onClick={async()=>{await cancelRecord("custos",r.id);reload()}}>Cancelar</button></span>])}/>:<EmptyTable heads={["Descrição","Data","Valor","Pago por","Status"]}/>}</>}{open&&<div className="overlay"><form className="modal" onSubmit={submit}><ModalHead title={edit?"Editar custo":"Novo custo"} close={()=>{setOpen(false);setEdit(null)}}/><label>Categoria<input name="categoria" defaultValue={edit?.categoria} required/></label><label>Descrição<input name="descricao" defaultValue={edit?.descricao} required/></label><div className="fields"><label>Valor<input name="valor" inputMode="decimal" defaultValue={edit?.valor?moneyText(edit.valor):""} placeholder="R$ 0,00" onBlur={e=>e.currentTarget.value=moneyText(parseMoney(e.currentTarget.value))} required/></label><label>Data<input name="data" type="date" defaultValue={edit?.data} required/></label></div><div className="fields"><label>Quem pagou<select name="socio" defaultValue={edit?.pago_por_socio_id??""}><option value="">Não informado</option>{partners.map(p=><option value={p.id} key={p.id}>{p.nome}</option>)}</select></label><label>Status<select name="status" defaultValue={edit?.status??"pendente"}><option value="pendente">Pendente</option><option value="pago">Pago</option></select></label></div><label>Observações<textarea name="observacoes" defaultValue={edit?.observacoes}/></label><button className="btn primary">Salvar</button></form></div>}</Module>
}
function AdvancesPage({tab,setTab,...periodProps}:{tab:string;setTab:(s:string)=>void}&PeriodProps){
 const {loadedPeriod}=periodProps,[rows,setRows]=useState<any[]>([]),[riders,setRiders]=useState<any[]>([]),[partners,setPartners]=useState<any[]>([]),[loading,setLoading]=useState(true),[open,setOpen]=useState(false),[error,setError]=useState("");
 const reload=async()=>{try{setLoading(true);const [a,r,p]=await Promise.all([loadAdvances(loadedPeriod),listRiders(),listPartners()]);setRows(a);setRiders(r);setPartners(p);setError("")}catch(e){setError(e instanceof Error?e.message:"Erro")}finally{setLoading(false)}};
 useEffect(()=>{reload()},[loadedPeriod]);
 const type=tab==="Extravios"?"extravio":"vale",visible=rows.filter(r=>r.tipo===type);
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);await saveAdvance({tipo:type,motoboy_id:f.get("motoboy"),valor:parseMoney(f.get("valor")),data:f.get("data"),periodo_desconto:loadedPeriod.numero_periodo,mes_desconto:loadedPeriod.mes,ano_desconto:loadedPeriod.ano,realizado_por_socio_id:f.get("socio")||null,status:"pendente",observacoes:f.get("observacoes")});setOpen(false);reload()};
 return <Module><PageHead title="Vales e Extravios" button="Novo lançamento" onAdd={()=>setOpen(true)}/><PeriodFilter {...periodProps}/><Tabs values={["Vales","Extravios"]} value={tab==="Extravios"?tab:"Vales"} set={setTab}/>{loading?<div className="data-state">Carregando vales e extravios...</div>:error?<div className="data-state error">{error}</div>:visible.length?<DataTable heads={["Motoboy","Tipo","Valor","Responsável","Status","Ações"]} rows={visible.map(r=>[r.motoboys?.nome,r.tipo,brl(Number(r.valor)),r.socios?.nome??"Não informado",<Status>{r.status}</Status>,<button className="details" onClick={async()=>{await cancelRecord("vales_extravios",r.id);reload()}}>Cancelar</button>])}/>:<EmptyTable heads={["Motoboy","Tipo","Valor","Responsável","Status"]}/>} {open&&<div className="overlay"><form className="modal" onSubmit={submit}><ModalHead title={type==="vale"?"Novo vale":"Novo extravio"} close={()=>setOpen(false)}/><label>Motoboy<select name="motoboy" required>{riders.map(r=><option value={r.id} key={r.id}>{r.nome}</option>)}</select></label><div className="fields"><label>Valor<input name="valor" inputMode="decimal" placeholder="R$ 0,00" onBlur={e=>e.currentTarget.value=moneyText(parseMoney(e.currentTarget.value))} required/></label><label>Data<input name="data" type="date" required/></label></div><label>Responsável<select name="socio"><option value="">Não informado</option>{partners.map(p=><option value={p.id} key={p.id}>{p.nome}</option>)}</select></label><label>Observações<textarea name="observacoes"/></label><button className="btn primary">Salvar</button></form></div>}</Module>
}
function SetupRequired(){return <div className="auth-shell"><div className="setup-card"><div className="brand-login"><TrendingUp/><span><b>Sub Flex</b>Financeiro</span></div><h1>Conexão pendente</h1><p>O aplicativo está preparado para usar o Supabase. Configure as duas variáveis de ambiente para ativar o login e os dados persistentes.</p><code>NEXT_PUBLIC_SUPABASE_URL</code><code>NEXT_PUBLIC_SUPABASE_ANON_KEY</code><small>Nenhuma chave privada deve ser colocada no navegador.</small></div></div>}
