 const shown=rows.filter(r=>r.type===(loadedPeriod.tipo_periodo==="semanal"?"Semanal":"Quinzenal")&&(catalogFilter==="Todas"||(catalogFilter==="Ativas"?r.active||r.hasReceipt:!r.active)));
 const update=(id:string,key:keyof CarrierRow,value:string)=>{setRows(x=>x.map(r=>r.id===id?{...r,[key]:value}:r));setDirty(x=>x+1)};
 const saveEdit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing)return;const form=new FormData(e.currentTarget);try{setEditError("");await updateCarrier(editing.id,String(form.get("nome")??""),form.get("frequencia")==="semanal"?"semanal":"quinzenal");setEditing(null);await reload(loadedPeriod);setSaveState("Cadastro atualizado")}catch(error){setEditError(error instanceof Error?error.message:"Não foi possível atualizar")}};
 const toggleCarrier=async(row:CarrierRow)=>{const action=row.active?"inativar":"reativar";if(!window.confirm(row.active?"Deseja realmente inativar esta transportadora? O histórico será preservado e ela deixará de aparecer em novos lançamentos.":"Deseja realmente reativar esta transportadora?"))return;try{await setCarrierActive(row.id,!row.active);await reload(loadedPeriod);setSaveState(`Transportadora ${action==="inativar"?"inativada":"reativada"}`)}catch(error){setSaveState(error instanceof Error?error.message:`Erro ao ${action}`)}};
 const reviewMove=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();try{setMoveError("");setMovePreview(await previewCarrierReceiptMove(loadedPeriod,destination))}catch(error){setMovePreview(null);setMoveError(error instanceof Error?error.message:"Não foi possível revisar os lançamentos")}};
 const confirmMove=async()=>{if(!movePreview||movePreview.conflictNames.length)return;try{setMoving(true);setMoveError("");const count=await moveCarrierReceipts(loadedPeriod,destination);setMoveOpen(false);setMovePreview(null);await reload(loadedPeriod);setSaveState(`${count} lançamento${count===1?"":"s"} movido${count===1?"":"s"}`)}catch(error){setMoveError(error instanceof Error?error.message:"Nenhum lançamento foi movido")}finally{setMoving(false)}};
