  {editing&&<div className="overlay"><form className="modal" onSubmit={saveEdit}><ModalHead title="Editar transportadora" close={()=>setEditing(null)}/><label>Nome<input name="nome" defaultValue={editing.name} required/></label><label>Frequência<select name="frequencia" defaultValue={editing.registrationType==="Semanal"?"semanal":"quinzenal"}><option value="semanal">Semanal</option><option value="quinzenal">Quinzenal</option></select></label>{editError&&<div className="data-state error">{editError}</div>}<div className="form-actions"><button type="button" className="btn ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="btn primary">Salvar alteração</button></div></form></div>}
