 if(!data)return <Module><PageHead title="BI Financeiro" onAdd={()=>{}}/><BiFilters draft={draft} setDraft={setDraft} apply={apply} partners={[]}/><div className="data-state">Consolidando dados financeiros...</div></Module>;
